#!/usr/bin/python3
from Crypto.Util.number import *

sus1337 = 15295865526991442899

# Convert to bytes
try:
    print(f"As bytes: {long_to_bytes(sus1337)}")
except:
    print("Could not convert to bytes")

# Check relationship with 1337
print(f"\nDivisible by 1337?: {sus1337 % 1337 == 0}")
if sus1337 % 1337 == 0:
    print(f"Result: {sus1337 // 1337}")

# Look for other mathematical relationships
print(f"\nLength in bits: {sus1337.bit_length()}")
print(f"Length in decimal digits: {len(str(sus1337))}")
print(f"In hex: {hex(sus1337)}")

# Check if it's a power or product involving 1337
import math

# Check if it's close to 1337^n
for n in range(2, 20):
    if abs(1337**n - sus1337) / sus1337 < 0.01:
        print(f"\nClose to 1337^{n}")

# Factor the number
def factors(n):
    factors = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            factors.append(i)
            if i != n//i:
                factors.append(n//i)
    return sorted(factors)

print("\nFactors:")
print(factors(sus1337))
